import { SiteConfig } from "@/site-config";
import { getSessionCookie } from "better-auth/cookies";
import type { NextRequest } from "next/server";

type SessionUser = {
  id: string;
  email: string;
  accountType?: string;
};

/**
 * Get user data from session for middleware
 * Note: Limited to cookie data only, no database queries allowed in middleware
 */
export async function getMiddlewareUser(request: NextRequest) {
  try {
    const session = getSessionCookie(request, {
      cookiePrefix: SiteConfig.appId,
    }) as { user: SessionUser } | string | null;

    if (!session || typeof session === "string") {
      return null;
    }

    // Return basic user data from cookie session
    // For full user data, make API call from page/component instead
    return {
      id: session.user.id,
      email: session.user.email,
      // Default to individual if not specified in cookie
      accountType: session.user.accountType ?? "individual",
    };
  } catch {
    return null;
  }
}

/**
 * Get redirect URL based on account type
 */
export function getRedirectUrl(accountType: string) {
  return accountType === "professional" ? "/orgs" : "/dashboard";
}

import type { Statements } from "better-auth/plugins/access";
import { createAccessControl } from "better-auth/plugins/access";
import {
  adminAc,
  defaultStatements,
  memberAc,
  ownerAc,
} from "better-auth/plugins/organization/access";
import { z } from "zod";

const statement = {
  ...defaultStatements,
  project: ["create", "share", "update", "delete"],
  subscription: ["manage"],
  users: ["create", "delete"],
} as const satisfies Statements;

export const AuthPermissionSchema = z.object(
  Object.fromEntries(
    Object.entries(statement).map(([key, actions]) => [
      key,
      z
        .array(z.enum([...actions] as unknown as [string, ...string[]]))
        .optional(),
    ]),
  ) as unknown as {
    [K in keyof typeof statement]: z.ZodOptional<
      z.ZodArray<
        z.ZodEnum<
          [
            ...((typeof statement)[K] extends readonly (infer T)[]
              ? T extends string
                ? (typeof statement)[K] extends readonly [string, ...string[]]
                  ? (typeof statement)[K]
                  : never
                : never
              : never),
          ]
        >
      >
    >;
  },
);

export type AuthPermission = z.infer<typeof AuthPermissionSchema>;

export const ac = createAccessControl(statement);

const member = ac.newRole({
  project: ["create"],
  users: ["create"],
  ...memberAc.statements,
});

const admin = ac.newRole({
  project: ["create", "update"],
  subscription: ["manage"],
  users: ["create", "delete"],
  ...adminAc.statements,
});

const owner = ac.newRole({
  ...(statement as Statements),
  ...ownerAc.statements,
});

export const roles = { member, admin, owner } as const;

export const RolesKeys = ["member", "admin", "owner"] as const;

export type AuthRole = keyof typeof roles;

