import { headers } from "next/headers";
import { auth } from "../auth";
import type { AuthPermission } from "./auth-permissions";
import { getUserContext, hasB2BPermissionAsync } from "./unified-permissions";
import type { B2BPermission } from "./b2b-permissions";

/**
 * Legacy permission checker - uses Better Auth organization permissions
 * This is maintained for backward compatibility with existing B2B organization features
 */
export const hasPermission = async (permission: AuthPermission) => {
  const result = await auth.api.hasPermission({
    headers: await headers(),
    body: {
      permission,
    },
  });

  return result.success;
};

/**
 * New unified permission checker
 * Automatically routes to B2C or B2B permissions based on account type
 */
export const hasUnifiedPermission = async (
  permission: AuthPermission | B2BPermission,
) => {
  const userContext = await getUserContext();

  if (!userContext) {
    return false;
  }

  // For professionals, use B2B permissions if it's a B2B-specific permission
  if (userContext.accountType === "professional") {
    try {
      // Try B2B permissions first
      return await hasB2BPermissionAsync(permission as B2BPermission);
    } catch {
      // Fall back to legacy organization permissions
      return hasPermission(permission as AuthPermission);
    }
  }

  // For individuals, B2B permissions don't apply
  return false;
};

import type { Statements } from "better-auth/plugins/access";
import { createAccessControl } from "better-auth/plugins/access";
import { z } from "zod";

/**
 * B2C Permissions for Individual Users (Particuliers)
 * These permissions apply to individual users who are house/apartment buyers
 */
const b2cStatements = {
  // Property management
  favorite: ["create", "read", "delete"], // Manage favorite properties
  comparison: ["create", "read", "update", "delete"], // Compare properties
  alert: ["create", "read", "update", "delete"], // Property alerts
  savedSearch: ["create", "read", "update", "delete"], // Saved search criteria

  // Financial tools
  simulation: ["create", "read", "update", "delete"], // Mortgage simulations
  budget: ["create", "read", "update"], // Budget calculations

  // Profile management
  profile: ["read", "update"], // User profile
  preferences: ["read", "update"], // Search preferences
  notifications: ["read", "update"], // Notification settings
} as const satisfies Statements;

export const B2CPermissionSchema = z.object(
  Object.fromEntries(
    Object.entries(b2cStatements).map(([key, actions]) => [
      key,
      z
        .array(z.enum([...actions] as unknown as [string, ...string[]]))
        .optional(),
    ]),
  ) as unknown as {
    [K in keyof typeof b2cStatements]: z.ZodOptional<
      z.ZodArray<
        z.ZodEnum<
          [
            ...((typeof b2cStatements)[K] extends readonly (infer T)[]
              ? T extends string
                ? (typeof b2cStatements)[K] extends readonly [
                    string,
                    ...string[],
                  ]
                  ? (typeof b2cStatements)[K]
                  : never
                : never
              : never),
          ]
        >
      >
    >;
  },
);

export type B2CPermission = z.infer<typeof B2CPermissionSchema>;

// Create access control for B2C
export const b2cAc = createAccessControl(b2cStatements);

// Define B2C user role (individual buyers)
const individualBuyer = b2cAc.newRole({
  // Full access to personal features
  favorite: ["create", "read", "delete"],
  comparison: ["create", "read", "update", "delete"],
  alert: ["create", "read", "update", "delete"],
  savedSearch: ["create", "read", "update", "delete"],
  simulation: ["create", "read", "update", "delete"],
  budget: ["create", "read", "update"],
  profile: ["read", "update"],
  preferences: ["read", "update"],
  notifications: ["read", "update"],
});

export const b2cRoles = { individualBuyer } as const;

export const B2CRolesKeys = ["individualBuyer"] as const;

export type B2CRole = keyof typeof b2cRoles;

// Helper functions for B2C permissions
export const hasB2CPermission = (
  userRole: B2CRole | undefined,
  resource: keyof typeof b2cStatements,
  action: string,
): boolean => {
  if (!userRole) {
    return false;
  }

  const role = b2cRoles[userRole];
  const resourcePermissions = role.statements[resource];

  return resourcePermissions.includes(action as never);
};

export const getB2CUserRole = (accountType: string): B2CRole | null => {
  if (accountType === "individual") {
    return "individualBuyer";
  }
  return null;
};

