import { redirect } from "next/navigation";
import { type ReactNode } from "react";
import type { B2CPermission } from "@/lib/auth/b2c-permissions";
import type { B2BPermission } from "@/lib/auth/b2b-permissions";
import {
  getUserContext,
  hasB2CPermissionAsync,
  hasB2BPermissionAsync,
} from "@/lib/auth/unified-permissions";

type PermissionGuardProps = {
  children: ReactNode;
  fallback?: ReactNode;
  redirectTo?: string;
} & (
  | {
      b2cPermission: B2CPermission;
      b2bPermission?: never;
    }
  | {
      b2cPermission?: never;
      b2bPermission: B2BPermission;
    }
  | {
      b2cPermission: B2CPermission;
      b2bPermission: B2BPermission;
    }
);

/**
 * Permission Guard Component
 * Protects content based on B2C or B2B permissions
 */
export async function PermissionGuard({
  children,
  fallback = null,
  redirectTo,
  b2cPermission,
  b2bPermission,
}: PermissionGuardProps) {
  const userContext = await getUserContext();

  if (!userContext) {
    if (redirectTo) {
      redirect("/auth/signin");
    }
    return <>{fallback}</>;
  }

  let hasPermission = false;

  // Check B2C permissions for individuals
  if (userContext.accountType === "individual" && b2cPermission) {
    hasPermission = await hasB2CPermissionAsync(b2cPermission);
  }

  // Check B2B permissions for professionals
  if (userContext.accountType === "professional" && b2bPermission) {
    hasPermission = await hasB2BPermissionAsync(b2bPermission);
  }

  if (!hasPermission) {
    if (redirectTo) {
      redirect(redirectTo);
    }
    return <>{fallback}</>;
  }

  return <>{children}</>;
}

type AccountTypeGuardProps = {
  children: ReactNode;
  accountType: "individual" | "professional";
  fallback?: ReactNode;
  redirectTo?: string;
};

/**
 * Account Type Guard Component
 * Protects content based on account type (B2C vs B2B)
 */
export async function AccountTypeGuard({
  children,
  accountType,
  fallback = null,
  redirectTo,
}: AccountTypeGuardProps) {
  const userContext = await getUserContext();

  if (!userContext) {
    if (redirectTo) {
      redirect("/auth/signin");
    }
    return <>{fallback}</>;
  }

  if (userContext.accountType !== accountType) {
    if (redirectTo) {
      const defaultRedirect =
        accountType === "individual" ? "/dashboard" : "/orgs";
      redirect(redirectTo || defaultRedirect);
    }
    return <>{fallback}</>;
  }

  return <>{children}</>;
}

type RoleGuardProps = {
  children: ReactNode;
  roles: string[];
  fallback?: ReactNode;
  redirectTo?: string;
};

/**
 * Role Guard Component
 * Protects content based on specific roles
 */
export async function RoleGuard({
  children,
  roles,
  fallback = null,
  redirectTo,
}: RoleGuardProps) {
  const userContext = await getUserContext();

  if (!userContext) {
    if (redirectTo) {
      redirect("/auth/signin");
    }
    return <>{fallback}</>;
  }

  // For professionals, check organization role
  if (userContext.accountType === "professional") {
    const hasRole =
      userContext.organizationRole &&
      roles.includes(userContext.organizationRole);

    if (!hasRole) {
      if (redirectTo) {
        redirect(redirectTo);
      }
      return <>{fallback}</>;
    }
  }

  // For individuals, only check if they have the "individualBuyer" role
  if (userContext.accountType === "individual") {
    const hasRole = roles.includes("individualBuyer");

    if (!hasRole) {
      if (redirectTo) {
        redirect(redirectTo);
      }
      return <>{fallback}</>;
    }
  }

  return <>{children}</>;
}

