     3→import { Typography } from "@/components/shared/typography";
     4→import {
     5→  Form,
     6→  FormControl,
     7→  FormField,
     8→  FormItem,
     9→  FormLabel,
    10→  FormMessage,
    11→  useZodForm,
    12→} from "@/components/ui/form";
    13→import { Input } from "@/components/ui/input";
    14→import { LoadingButton } from "@/features/form/submit-button";
    15→import { authClient } from "@/lib/auth-client";
    16→import { getCallbackUrl } from "@/lib/auth/auth-utils";
    17→import { unwrapSafePromise } from "@/lib/promises";
    18→import { useMutation } from "@tanstack/react-query";
    19→import Link from "next/link";
    20→import { useLocalStorage } from "react-use";
    21→import { toast } from "sonner";
    22→import { z } from "zod";
    23→
    24→const LoginCredentialsFormScheme = z.object({
    25→  email: z.string().email(),
    26→  password: z.string().optional(),
    27→});
    28→
    29→type LoginCredentialsFormType = z.infer<typeof LoginCredentialsFormScheme>;
    30→
    31→export const SignInCredentialsAndMagicLinkForm = (props: {
    32→  callbackUrl?: string;
    33→}) => {
    34→  const form = useZodForm({
    35→    schema: LoginCredentialsFormScheme,
    36→    defaultValues: {
    37→      email: "",
    38→      password: "",
    39→    },
    40→  });
    41→  const [isUsingCredentials, setIsUsingCredentials] = useLocalStorage(
    42→    "sign-in-with-credentials",
    43→    true,
    44→  );
    45→
    46→  const signInMutation = useMutation({
    47→    mutationFn: async (values: LoginCredentialsFormType) => {
    48→      if (isUsingCredentials) {
    49→        return unwrapSafePromise(
    50→          authClient.signIn.email({
    51→            email: values.email,
    52→            password: values.password ?? "",
    53→            rememberMe: true,
    54→          }),
    55→        );
    56→      } else {
    57→        return unwrapSafePromise(
    58→          authClient.signIn.magicLink({
    59→            email: values.email,
    60→            callbackURL: getCallbackUrl(props.callbackUrl ?? "/orgs"),
    61→          }),
    62→        );
    63→      }
    64→    },
    65→    onError: (error) => {
    66→      toast.error(error.message);
    67→    },
    68→    onSuccess: () => {
    69→      const callbackUrl = getCallbackUrl(props.callbackUrl ?? "/orgs");
    70→      const newUrl =
    71→        window.location.origin +
    72→        (isUsingCredentials ? callbackUrl : "/auth/verify");
    73→      window.location.href = newUrl;
    74→    },
    75→  });
    76→
    77→  function onSubmit(values: LoginCredentialsFormType) {
    78→    signInMutation.mutate(values);
    79→  }
    80→
    81→  return (
    82→    <Form form={form} onSubmit={onSubmit} className="max-w-lg space-y-4">
    83→      <FormField
    84→        control={form.control}
    85→        name="email"
    86→        render={({ field }) => (
    87→          <FormItem>
    88→            <FormLabel>Email</FormLabel>
    89→            <FormControl>
    90→              <Input placeholder="john@doe.com" {...field} />
    91→            </FormControl>
    92→            <FormMessage />
    93→          </FormItem>
    94→        )}
    95→      />
    96→      {isUsingCredentials ? (
    97→        <FormField
    98→          control={form.control}
    99→          name="password"
   100→          render={({ field }) => (
   101→            <FormItem className="flex-1">
   102→              <div className="flex items-center justify-between">
   103→                <FormLabel>Password</FormLabel>
   104→                <Link
   105→                  href="/auth/forget-password"
   106→                  className="text-sm underline"
   107→                >
   108→                  Forgot password ?
   109→                </Link>
   110→              </div>
   111→              <FormControl>
   112→                <Input type="password" {...field} />
   113→              </FormControl>
   114→              <FormMessage />
   115→            </FormItem>
   116→          )}
   117→        />
   118→      ) : null}
   119→
   120→      <LoadingButton
   121→        loading={signInMutation.isPending}
   122→        type="submit"
   123→        className="ring-offset-card w-full ring-offset-2"
   124→      >
   125→        {isUsingCredentials ? "Se connecter" : "Se connecter avec lien magique"}
   126→      </LoadingButton>
   127→
   128→      {isUsingCredentials ? (
   129→        <Typography variant="muted" className="text-xs">
   130→          Vous voulez vous connecter plus rapidement ?{" "}
   131→          <Typography
   132→            variant="link"
   133→            as="button"
   134→            type="button"
   135→            onClick={() => {
   136→              setIsUsingCredentials(false);
   137→            }}
   138→          >
   139→            Connexion avec lien magique
   140→          </Typography>
   141→        </Typography>
   142→      ) : (
   143→        <Typography variant="muted" className="text-xs">
   144→          Vous préférez la connexion par mot de passe ?{" "}
   145→          <Typography
   146→            variant="link"
   147→            as="button"
   148→            type="button"
   149→            onClick={() => {
   150→              setIsUsingCredentials(true);
   151→            }}
   152→          >
   153→            Utiliser un mot de passe
   154→          </Typography>
   155→        </Typography>
   156→      )}
   157→    </Form>
   158→  );
   159→};
