import { redirect } from "next/navigation";
import { type ReactNode } from "react";
import type { B2CPermission } from "@/lib/auth/b2c-permissions";
import { getB2CUserRole, hasB2CPermission } from "@/lib/auth/b2c-permissions";
import { getUser } from "@/lib/auth/auth-user";

type PermissionGuardProps = {
  children: ReactNode;
  fallback?: ReactNode;
  redirectTo?: string;
  permission: B2CPermission;
};

export async function PermissionGuard({
  children,
  fallback = null,
  redirectTo,
  permission,
}: PermissionGuardProps) {
  const user = await getUser();

  if (!user) {
    if (redirectTo) {
      redirect("/auth/signin");
    }
    return <>{fallback}</>;
  }

  const userRole = getB2CUserRole("individual");
  if (!userRole) {
    if (redirectTo) {
      redirect(redirectTo);
    }
    return <>{fallback}</>;
  }

  const permissionKeys = Object.keys(permission) as (keyof B2CPermission)[];
  let hasAllPermissions = true;

  for (const key of permissionKeys) {
    const actions = permission[key];
    if (actions) {
      for (const action of actions) {
        if (!hasB2CPermission(userRole, key, action)) {
          hasAllPermissions = false;
          break;
        }
      }
    }
    if (!hasAllPermissions) break;
  }

  if (!hasAllPermissions) {
    if (redirectTo) {
      redirect(redirectTo);
    }
    return <>{fallback}</>;
  }

  return <>{children}</>;
}

type AuthGuardProps = {
  children: ReactNode;
  fallback?: ReactNode;
  redirectTo?: string;
};

export async function AuthGuard({
  children,
  fallback = null,
  redirectTo = "/auth/signin",
}: AuthGuardProps) {
  const user = await getUser();

  if (!user) {
    if (redirectTo) {
      redirect(redirectTo);
    }
    return <>{fallback}</>;
  }

  return <>{children}</>;
}

