"use client";

import { Button } from "@/components/ui/button";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
  useZodForm,
} from "@/components/ui/form";
import { Input } from "@/components/ui/input";
import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { User, Building2 } from "lucide-react";
import { authClient } from "@/lib/auth-client";
import { getCallbackUrl } from "@/lib/auth/auth-utils";
import { unwrapSafePromise } from "@/lib/promises";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import type { LoginCredentialsFormType } from "./signup.schema";
import { LoginCredentialsFormScheme } from "./signup.schema";
import { updateAccountTypeAction } from "@/features/auth/update-account-type.action";

export const SignUpCredentialsForm = () => {
  const form = useZodForm({
    schema: LoginCredentialsFormScheme,
    defaultValues: {
      name: "",
      email: "",
      password: "",
      verifyPassword: "",
      image: "",
      accountType: "individual" as const,
    },
  });

  const submitMutation = useMutation({
    mutationFn: async (values: LoginCredentialsFormType) => {
      // First, create the user account
      const signUpResult = await unwrapSafePromise(
        authClient.signUp.email({
          email: values.email,
          password: values.password,
          name: values.name,
          image: values.image,
        }),
      );

      // Then update account type
      const updateResult = await updateAccountTypeAction(values.accountType);
      if (!updateResult.success) {
        throw new Error(updateResult.error ?? "Failed to set account type");
      }

      return { signUpResult, accountType: values.accountType };
    },
    onError: (error) => {
      toast.error(error.message);
    },
    onSuccess: (data) => {
      // Redirect based on account type
      const redirectUrl =
        data.accountType === "professional"
          ? getCallbackUrl("/orgs")
          : getCallbackUrl("/dashboard");

      toast.success(
        `Compte ${data.accountType === "professional" ? "professionnel" : "particulier"} créé avec succès !`,
      );

      const newUrl = window.location.origin + redirectUrl;
      window.location.href = newUrl;
    },
  });

  async function onSubmit(values: LoginCredentialsFormType) {
    if (values.password !== values.verifyPassword) {
      form.setError("verifyPassword", {
        message: "Password does not match",
      });
      return;
    }

    return submitMutation.mutateAsync(values);
  }

  return (
    <Form
      form={form}
      onSubmit={async (values) => {
        return onSubmit(values);
      }}
      className="max-w-lg space-y-4"
    >
      <FormField
        control={form.control}
        name="accountType"
        render={({ field }) => (
          <FormItem>
            <FormLabel>Type de compte</FormLabel>
            <FormControl>
              <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
                <Card
                  className={`cursor-pointer transition-colors ${
                    field.value === "individual"
                      ? "border-blue-500 ring-2 ring-blue-500"
                      : "hover:border-gray-300"
                  }`}
                  onClick={() => field.onChange("individual")}
                >
                  <CardHeader className="pb-3">
                    <div className="flex items-center space-x-2">
                      <User className="h-5 w-5 text-blue-600" />
                      <div>
                        <CardTitle className="text-base">Particulier</CardTitle>
                        <CardDescription className="text-sm">
                          Je cherche un bien à acheter ou louer
                        </CardDescription>
                      </div>
                    </div>
                  </CardHeader>
                </Card>

                <Card
                  className={`cursor-pointer transition-colors ${
                    field.value === "professional"
                      ? "border-blue-500 ring-2 ring-blue-500"
                      : "hover:border-gray-300"
                  }`}
                  onClick={() => field.onChange("professional")}
                >
                  <CardHeader className="pb-3">
                    <div className="flex items-center space-x-2">
                      <Building2 className="h-5 w-5 text-blue-600" />
                      <div>
                        <CardTitle className="text-base">
                          Professionnel
                        </CardTitle>
                        <CardDescription className="text-sm">
                          Je représente une agence immobilière
                        </CardDescription>
                      </div>
                    </div>
                  </CardHeader>
                </Card>
              </div>
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />

      <FormField
        control={form.control}
        name="name"
        render={({ field }) => (
          <FormItem>
            <FormLabel>Nom complet</FormLabel>
            <FormControl>
              <Input placeholder="Jean Dupont" {...field} />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name="email"
        render={({ field }) => (
          <FormItem>
            <FormLabel>Email</FormLabel>
            <FormControl>
              <Input placeholder="jean.dupont@email.com" {...field} />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name="password"
        render={({ field }) => (
          <FormItem>
            <FormLabel>Mot de passe</FormLabel>
            <FormControl>
              <Input
                type="password"
                placeholder="8 caractères minimum"
                {...field}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />
      <FormField
        control={form.control}
        name="verifyPassword"
        render={({ field }) => (
          <FormItem>
            <FormLabel>Confirmez le mot de passe</FormLabel>
            <FormControl>
              <Input
                type="password"
                placeholder="Répétez votre mot de passe"
                {...field}
              />
            </FormControl>
            <FormMessage />
          </FormItem>
        )}
      />

      <Button
        type="submit"
        className="w-full"
        disabled={submitMutation.isPending}
      >
        {submitMutation.isPending
          ? "Création du compte..."
          : "Créer mon compte"}
      </Button>
    </Form>
  );
};

