"use client";

import { logger } from "@/lib/logger";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { SafeImage } from "@/components/ui/safe-image";
import type { Property } from "@/lib/moteurimmo/types";
import { useState } from "react";
import { usePathname } from "next/navigation";
import { toggleFavoriteAction } from "@/features/favorites/favorites.action";
import { ComparisonButton } from "@/features/comparison/comparison-button";
import { FinanceButton } from "@/features/finance/finance-button";
import {
  Bed,
  Calendar,
  Heart,
  Home,
  MapPin,
  Ruler,
  ExternalLink,
  ArrowRight,
} from "lucide-react";
import Link from "next/link";
import { cn } from "@/lib/utils";

type PropertyCardProps = {
  property: Property;
  view?: "list" | "grid";
  onFavorite?: (property: Property) => void;
  isFavorite?: boolean;
};

export function PropertyCard({
  property,
  view = "list",
  onFavorite,
  isFavorite = false,
}: PropertyCardProps) {
  const pathname = usePathname();
  const isInOrgContext = pathname.startsWith("/orgs/");
  const detailUrl = isInOrgContext
    ? `${pathname}/${property.id}`
    : `/properties/${property.id}`;
  const [isFavorited, setIsFavorited] = useState(isFavorite);
  const [isLoading, setIsLoading] = useState(false);

  const handleFavoriteClick = async () => {
    if (isLoading) return;

    setIsLoading(true);
    try {
      const result = await toggleFavoriteAction(property.uniqueId);
      setIsFavorited(result.isFavorite);
      onFavorite?.(property);
    } catch (error) {
      logger.debug("Erreur lors de la mise à jour du favori:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const formatPrice = (price: number) => {
    return new Intl.NumberFormat("fr-FR", {
      style: "currency",
      currency: "EUR",
      maximumFractionDigits: 0,
    }).format(price);
  };

  const formatDate = (dateString: string) => {
    return new Intl.DateTimeFormat("fr-FR", {
      day: "numeric",
      month: "short",
    }).format(new Date(dateString));
  };

  const getTypeLabel = (type: string) => {
    return type === "sale" ? "Vente" : "Location";
  };

  const getCategoryLabel = (category: string) => {
    const labels = {
      flat: "Appartement",
      house: "Maison",
      land: "Terrain",
      office: "Bureau",
      shop: "Commerce",
      warehouse: "Entrepôt",
      building: "Immeuble",
      "parking/garage/box": "Parking",
    };
    return labels[category as keyof typeof labels] || category;
  };

  const pricePerSqm = property.surface
    ? Math.round(property.price / property.surface)
    : null;

  if (view === "grid") {
    return (
      <div className="glass-card group overflow-hidden transition-all duration-300 hover:scale-[1.02] hover:shadow-[0_20px_40px_rgba(0,0,0,0.3),0_0_40px_var(--glow-accent)]">
        <div className="relative aspect-[4/3] overflow-hidden">
          <SafeImage
            src={property.mainImage ?? property.images[0]}
            alt={property.title}
            fill
            className="object-cover transition-transform duration-500 group-hover:scale-110"
          />
          <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />
          <div className="absolute top-3 left-3 flex gap-2">
            <Badge variant="glass">{getTypeLabel(property.type)}</Badge>
            <Badge
              variant="outline"
              className="border-white/20 bg-black/30 text-white"
            >
              {getCategoryLabel(property.category)}
            </Badge>
          </div>
          <Button
            variant="ghost"
            size="icon"
            className={cn(
              "absolute top-3 right-3 rounded-xl bg-black/30 backdrop-blur-sm transition-all duration-200",
              isFavorited
                ? "text-red-500 hover:bg-red-500/20"
                : "text-white hover:bg-white/10",
            )}
            onClick={handleFavoriteClick}
          >
            <Heart className={cn("size-5", isFavorited && "fill-red-500")} />
          </Button>
          <div className="absolute right-3 bottom-3 left-3">
            <div className="text-2xl font-bold text-white drop-shadow-lg">
              {formatPrice(property.price)}
            </div>
            {pricePerSqm && (
              <div className="text-sm text-white/80">
                {formatPrice(pricePerSqm)}/m²
              </div>
            )}
          </div>
        </div>

        <div className="space-y-3 p-4">
          <h3 className="text-foreground line-clamp-2 text-lg leading-tight font-semibold">
            {property.title}
          </h3>
          <div className="text-muted-foreground flex items-center gap-1.5 text-sm">
            <MapPin className="text-primary size-4" />
            <span className="truncate">
              {property.city}
              {property.postalCode && ` (${property.postalCode})`}
            </span>
          </div>

          <div className="text-muted-foreground flex items-center gap-4 text-sm">
            {property.surface && (
              <div className="flex items-center gap-1.5">
                <Ruler className="size-4" />
                <span>{property.surface}m²</span>
              </div>
            )}
            {property.rooms && (
              <div className="flex items-center gap-1.5">
                <Home className="size-4" />
                <span>{property.rooms} pièces</span>
              </div>
            )}
            {property.bedrooms && (
              <div className="flex items-center gap-1.5">
                <Bed className="size-4" />
                <span>{property.bedrooms}</span>
              </div>
            )}
          </div>

          <div className="flex items-center justify-between border-t border-[var(--border-subtle)] pt-2">
            <div className="text-muted-foreground flex items-center gap-1.5 text-xs">
              <Calendar className="size-3" />
              <span>{formatDate(property.createdAt)}</span>
            </div>
            <div className="flex gap-1.5">
              <ComparisonButton property={property} />
              <FinanceButton property={property} showText={false} />
              <Button size="sm" variant="accent" asChild>
                <Link href={detailUrl}>
                  Voir
                  <ArrowRight className="ml-1 size-3" />
                </Link>
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="glass-card group overflow-hidden transition-all duration-300 hover:shadow-[0_10px_30px_rgba(0,0,0,0.3),0_0_30px_var(--glow-accent)]">
      <div className="flex">
        <div className="relative aspect-[4/3] w-56 flex-shrink-0 overflow-hidden">
          <SafeImage
            src={property.mainImage ?? property.images[0]}
            alt={property.title}
            fill
            className="object-cover transition-transform duration-500 group-hover:scale-105"
          />
          <div className="absolute inset-0 bg-gradient-to-r from-transparent to-[var(--brand-surface)]" />
          <Button
            variant="ghost"
            size="icon"
            className={cn(
              "absolute top-3 right-3 rounded-xl bg-black/30 backdrop-blur-sm transition-all duration-200",
              isFavorited
                ? "text-red-500 hover:bg-red-500/20"
                : "text-white hover:bg-white/10",
            )}
            onClick={handleFavoriteClick}
          >
            <Heart className={cn("size-5", isFavorited && "fill-red-500")} />
          </Button>
        </div>

        <div className="flex-1 p-4">
          <div className="mb-3 flex items-start justify-between">
            <div className="flex gap-2">
              <Badge variant="accent">{getTypeLabel(property.type)}</Badge>
              <Badge variant="outline">
                {getCategoryLabel(property.category)}
              </Badge>
            </div>
            <div className="text-muted-foreground flex items-center gap-1.5 text-xs">
              <Calendar className="size-3" />
              <span>{formatDate(property.createdAt)}</span>
            </div>
          </div>

          <h3 className="text-foreground mb-2 line-clamp-2 text-lg font-semibold">
            {property.title}
          </h3>

          <div className="text-muted-foreground mb-3 flex items-center gap-1.5 text-sm">
            <MapPin className="text-primary size-4" />
            <span>
              {property.city}
              {property.postalCode && ` (${property.postalCode})`}
            </span>
          </div>

          {property.description && (
            <p className="text-muted-foreground mb-3 line-clamp-2 text-sm">
              {property.description}
            </p>
          )}

          <div className="flex items-end justify-between">
            <div>
              <div className="text-gradient-accent text-2xl font-bold">
                {formatPrice(property.price)}
              </div>
              {pricePerSqm && (
                <div className="text-muted-foreground text-sm">
                  {formatPrice(pricePerSqm)}/m²
                </div>
              )}
            </div>

            <div className="text-muted-foreground flex items-center gap-4 text-sm">
              {property.surface && (
                <div className="flex items-center gap-1.5">
                  <Ruler className="size-4" />
                  <span>{property.surface}m²</span>
                </div>
              )}
              {property.rooms && (
                <div className="flex items-center gap-1.5">
                  <Home className="size-4" />
                  <span>{property.rooms} pièces</span>
                </div>
              )}
              {property.bedrooms && (
                <div className="flex items-center gap-1.5">
                  <Bed className="size-4" />
                  <span>{property.bedrooms}</span>
                </div>
              )}
            </div>

            <div className="flex gap-2">
              <ComparisonButton property={property} />
              <FinanceButton property={property} showText={false} />
              {property.url && (
                <Button variant="outline" size="sm" asChild>
                  <Link href={property.url} target="_blank">
                    <ExternalLink className="size-4" />
                  </Link>
                </Button>
              )}
              <Button size="sm" variant="accent" asChild>
                <Link href={detailUrl}>
                  Voir détails
                  <ArrowRight className="ml-1 size-4" />
                </Link>
              </Button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

