"use client";

import { logger } from "@/lib/logger";
import { useState } from "react";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Search, Play, Pause, Trash2, Clock } from "lucide-react";
import {
  deleteSavedSearchAction,
  toggleSavedSearchAction,
  applySavedSearchAction,
} from "./saved-searches.action";
import { useRouter } from "next/navigation";
import { propertySearchSerializer } from "@/features/properties/search-params";
import type { SavedSearch } from "@/generated/prisma";

type SavedSearchCardProps = {
  savedSearch: SavedSearch;
  onUpdate: () => void;
};

export function SavedSearchCard({
  savedSearch,
  onUpdate,
}: SavedSearchCardProps) {
  const [isLoading, setIsLoading] = useState(false);
  const router = useRouter();

  const handleToggle = async () => {
    setIsLoading(true);
    try {
      await toggleSavedSearchAction(savedSearch.id, !savedSearch.isActive);
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la mise à jour:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async () => {
    if (
      !confirm(
        `Êtes-vous sûr de vouloir supprimer la recherche "${savedSearch.name}" ?`,
      )
    ) {
      return;
    }

    setIsLoading(true);
    try {
      await deleteSavedSearchAction(savedSearch.id);
      onUpdate();
    } catch (error) {
      logger.debug("Erreur lors de la suppression:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleApply = async () => {
    setIsLoading(true);
    try {
      const search = await applySavedSearchAction(savedSearch.id);

      // Build URL with filters - use current org path
      logger.debug("🔍 Applying saved search criteria:", search.criteria);

      const searchParams = propertySearchSerializer(
        search.criteria as Record<string, unknown>,
      );

      logger.debug("🔗 Generated search params:", searchParams);

      // Get current org from URL
      const currentPath = window.location.pathname;
      const orgMatch = currentPath.match(/\/orgs\/([^/]+)/);
      const orgSlug = orgMatch ? orgMatch[1] : "";

      const url = orgSlug
        ? `/orgs/${orgSlug}/properties?${searchParams}`
        : `/properties?${searchParams}`;

      logger.debug("🎯 Navigating to:", url);
      router.push(url);
    } catch (error) {
      logger.debug("❌ Erreur lors de l'application:", error);
    } finally {
      setIsLoading(false);
    }
  };

  const criteria = savedSearch.criteria as Record<string, unknown>;

  return (
    <Card className="transition-shadow hover:shadow-md">
      <CardHeader className="pb-3">
        <div className="flex items-start justify-between">
          <div className="min-w-0 flex-1 space-y-1">
            <div className="flex items-center gap-2">
              <h3 className="truncate font-semibold">{savedSearch.name}</h3>
              <Badge
                variant={savedSearch.isActive ? "default" : "secondary"}
                className="flex-shrink-0 text-xs"
              >
                {savedSearch.isActive ? "Active" : "Inactive"}
              </Badge>
            </div>
            <div className="text-muted-foreground flex items-center gap-4 text-xs">
              <div className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {savedSearch.frequency === "realtime"
                  ? "Temps réel"
