"use server";

import { prisma } from "@/lib/prisma";
import { getUser } from "@/lib/auth/auth-user";
import { logger } from "@/lib/logger";
import type { AccountType } from "@/types/auth";
import { auth } from "@/lib/auth";
import { generateSlug } from "@/lib/format/id";
import { getServerUrl } from "@/lib/server-url";

export async function updateAccountTypeAction(accountType: AccountType) {
  try {
    const currentUser = await getUser();

    if (!currentUser) {
      throw new Error("User not authenticated");
    }

    // Update user accountType
    const updatedUser = await prisma.user.update({
      where: { id: currentUser.id },
      data: { accountType },
    });

    logger.debug(
      `Updated user ${currentUser.id} accountType to ${accountType}`,
    );

    // If professional, create organization
    if (accountType === "professional") {
      const emailName = currentUser.email.slice(0, 8);
      try {
        await auth.api.createOrganization({
          body: {
            name: `${emailName}'s agency`,
            slug: generateSlug(`${emailName}-agency`),
            logo: `${getServerUrl()}/images/org-logo.png`,
            userId: currentUser.id,
            keepCurrentActiveOrganization: false,
          },
        });
        logger.debug(
          `Created organization for professional user ${currentUser.id}`,
        );
      } catch (err) {
        logger.error("Failed to create organization for professional user", {
          err,
          userId: currentUser.id,
        });
        // Don't throw here, user creation should still succeed
      }
    }

    return { success: true, user: updatedUser };
  } catch (error) {
    logger.error("Failed to update account type", { error, accountType });
    return {
      success: false,
      error: error instanceof Error ? error.message : "Unknown error",
    };
  }
}

