     5→import type { B2CPermission, B2CRole } from "@/lib/auth/b2c-permissions";
     6→import type { B2BPermission, B2BRole } from "@/lib/auth/b2b-permissions";
     7→
     8→type UserContext = {
     9→  id: string;
    10→  email: string;
    11→  accountType: "individual" | "professional";
    12→  organizationRole?: string;
    13→  organizationId?: string;
    14→};
    15→
    16→/**
    17→ * Hook to get user context with permissions info
    18→ */
    19→export function useUserContext() {
    20→  const { data: session } = useSession();
    21→
    22→  return useQuery({
    23→    queryKey: ["user-context", session?.user.id],
    24→    queryFn: async (): Promise<UserContext | null> => {
    25→      if (!session?.user) {
    26→        return null;
    27→      }
    28→
    29→      const response = await fetch("/api/auth/context");
    30→      if (!response.ok) {
    31→        return null;
    32→      }
    33→
    34→      return response.json();
    35→    },
    36→    enabled: Boolean(session?.user),
    37→  });
    38→}
    39→
    40→/**
    41→ * Hook to check if user has B2C permissions
    42→ */
    43→export function useB2CPermission(permission: B2CPermission) {
    44→  const { data: userContext } = useUserContext();
    45→
    46→  return useQuery({
    47→    queryKey: ["b2c-permission", userContext?.id, permission],
    48→    queryFn: async (): Promise<boolean> => {
    49→      if (!userContext || userContext.accountType !== "individual") {
    50→        return false;
    51→      }
    52→
    53→      const response = await fetch("/api/auth/permissions/b2c", {
    54→        method: "POST",
    55→        headers: { "Content-Type": "application/json" },
    56→        body: JSON.stringify({ permission }),
    57→      });
    58→
    59→      if (!response.ok) {
    60→        return false;
    61→      }
    62→
    63→      const result = await response.json();
    64→      return result.hasPermission;
    65→    },
    66→    enabled: !!userContext && userContext.accountType === "individual",
    67→  });
    68→}
    69→
    70→/**
    71→ * Hook to check if user has B2B permissions
    72→ */
    73→export function useB2BPermission(permission: B2BPermission) {
    74→  const { data: userContext } = useUserContext();
    75→
    76→  return useQuery({
    77→    queryKey: ["b2b-permission", userContext?.id, permission],
    78→    queryFn: async (): Promise<boolean> => {
    79→      if (!userContext || userContext.accountType !== "professional") {
    80→        return false;
    81→      }
    82→
    83→      const response = await fetch("/api/auth/permissions/b2b", {
    84→        method: "POST",
    85→        headers: { "Content-Type": "application/json" },
    86→        body: JSON.stringify({ permission }),
    87→      });
    88→
    89→      if (!response.ok) {
    90→        return false;
    91→      }
    92→
    93→      const result = await response.json();
    94→      return result.hasPermission;
    95→    },
    96→    enabled: !!userContext && userContext.accountType === "professional",
    97→  });
    98→}
    99→
   100→/**
   101→ * Hook to get user role
   102→ */
   103→export function useUserRole() {
   104→  const { data: userContext } = useUserContext();
   105→
   106→  return useQuery({
   107→    queryKey: ["user-role", userContext?.id],
   108→    queryFn: async (): Promise<B2CRole | B2BRole | null> => {
   109→      if (!userContext) {
   110→        return null;
   111→      }
   112→
   113→      const response = await fetch("/api/auth/role");
   114→      if (!response.ok) {
   115→        return null;
   116→      }
   117→
   118→      const result = await response.json();
   119→      return result.role;
   120→    },
   121→    enabled: !!userContext,
   122→  });
   123→}
   124→
   125→/**
   126→ * Hook to check account type
   127→ */
   128→export function useAccountType() {
   129→  const { data: userContext } = useUserContext();
   130→
   131→  return {
   132→    accountType: userContext?.accountType,
   133→    isIndividual: userContext?.accountType === "individual",
   134→    isProfessional: userContext?.accountType === "professional",
   135→    isLoading: !userContext,
   136→  };
   137→}
   138→
   139→/**
   140→ * Hook for conditional rendering based on permissions
   141→ */
