"use client";

import { useSession } from "@/lib/auth-client";
import { useQuery } from "@tanstack/react-query";
import type { B2CPermission, B2CRole } from "@/lib/auth/b2c-permissions";
import type { B2BPermission, B2BRole } from "@/lib/auth/b2b-permissions";

type UserContext = {
  id: string;
  email: string;
  accountType: "individual" | "professional";
  organizationRole?: string;
  organizationId?: string;
};

/**
 * Hook to get user context with permissions info
 */
export function useUserContext() {
  const { data: session } = useSession();

  return useQuery({
    queryKey: ["user-context", session?.user.id],
    queryFn: async (): Promise<UserContext | null> => {
      if (!session?.user) {
        return null;
      }

      const response = await fetch("/api/auth/context");
      if (!response.ok) {
        return null;
      }

      return response.json();
    },
    enabled: Boolean(session?.user),
  });
}

/**
 * Hook to check if user has B2C permissions
 */
export function useB2CPermission(permission: B2CPermission) {
  const { data: userContext } = useUserContext();

  return useQuery({
    queryKey: ["b2c-permission", userContext?.id, permission],
    queryFn: async (): Promise<boolean> => {
      if (!userContext || userContext.accountType !== "individual") {
        return false;
      }

      const response = await fetch("/api/auth/permissions/b2c", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ permission }),
      });

      if (!response.ok) {
        return false;
      }

      const result = await response.json();
      return result.hasPermission;
    },
    enabled: !!userContext && userContext.accountType === "individual",
  });
}

/**
 * Hook to check if user has B2B permissions
 */
export function useB2BPermission(permission: B2BPermission) {
  const { data: userContext } = useUserContext();

  return useQuery({
    queryKey: ["b2b-permission", userContext?.id, permission],
    queryFn: async (): Promise<boolean> => {
      if (!userContext || userContext.accountType !== "professional") {
        return false;
      }

      const response = await fetch("/api/auth/permissions/b2b", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ permission }),
      });

      if (!response.ok) {
        return false;
      }

      const result = await response.json();
      return result.hasPermission;
    },
    enabled: !!userContext && userContext.accountType === "professional",
  });
}

/**
 * Hook to get user role
 */
export function useUserRole() {
  const { data: userContext } = useUserContext();

  return useQuery({
    queryKey: ["user-role", userContext?.id],
    queryFn: async (): Promise<B2CRole | B2BRole | null> => {
      if (!userContext) {
        return null;
      }

      const response = await fetch("/api/auth/role");
      if (!response.ok) {
        return null;
      }

      const result = await response.json();
      return result.role;
    },
    enabled: !!userContext,
  });
}

/**
 * Hook to check account type
 */
export function useAccountType() {
  const { data: userContext } = useUserContext();

  return {
    accountType: userContext?.accountType,
    isIndividual: userContext?.accountType === "individual",
    isProfessional: userContext?.accountType === "professional",
    isLoading: !userContext,
  };
}

/**
 * Hook for conditional rendering based on permissions
 */
export function usePermissionGuard() {
  const { data: userContext } = useUserContext();

  return {
    canAccess: (_permission: B2CPermission | B2BPermission) => {
      // This would need to be implemented with proper permission checking
      // For now, return basic access based on account type
      return Boolean(userContext);
    },

    canAccessB2C: (_permission: B2CPermission) => {
      return userContext?.accountType === "individual";
    },

    canAccessB2B: (_permission: B2BPermission) => {
      return userContext?.accountType === "professional";
    },

    requiresAuth: !userContext,
    accountType: userContext?.accountType,
  };
}

