import { useQuery } from "@tanstack/react-query";
import type { B2CPermission, B2CRole } from "@/lib/auth/b2c-permissions";
import { hasB2CPermission, getB2CUserRole } from "@/lib/auth/b2c-permissions";

export function useUserContext() {
  const { data: session } = useSession();

  return useQuery({
    queryKey: ["user-context", session?.user.id],
    queryFn: async () => {
      if (!session?.user) {
        return null;
      }

      return {
        id: session.user.id,
        email: session.user.email,
        name: session.user.name,
      };
    },
    enabled: Boolean(session?.user),
  });
}

export function useB2CPermission(permission: B2CPermission) {
  const { data: session } = useSession();

  return useQuery({
    queryKey: ["b2c-permission", session?.user.id, permission],
    queryFn: async (): Promise<boolean> => {
      if (!session?.user) {
        return false;
      }

      const userRole = getB2CUserRole("individual");
      if (!userRole) return false;

      const permissionKeys = Object.keys(permission) as (keyof B2CPermission)[];
      for (const key of permissionKeys) {
        const actions = permission[key];
        if (actions) {
          for (const action of actions) {
            if (!hasB2CPermission(userRole, key, action)) {
              return false;
            }
          }
        }
      }

      return true;
    },
    enabled: Boolean(session?.user),
  });
}

