import { logger } from "@/lib/logger";
import { faker } from "@faker-js/faker";
import { nanoid } from "nanoid";
import { prisma } from "../src/lib/prisma";

// Set seed for reproducibility
faker.seed(123);

async function main() {
  logger.info("🌱 Seeding database...");

  // Create 10 users (mix of individual and professional)
  const userCreatePromises = Array.from({ length: 10 }, async (_, index) => {
    const email = faker.internet.email();
    // First 6 users will potentially be professionals (org members)
    // Last 4 users will be individuals
    const accountType = index < 6 ? "individual" : "individual"; // Will be updated later for org members

    return prisma.user.upsert({
      where: { email },
      update: {},
      create: {
        id: nanoid(11),
        name: faker.person.fullName(),
        email,
        emailVerified: faker.datatype.boolean(0.8), // 80% chance of being verified
        image: faker.image.avatar(),
        accountType,
        createdAt: faker.date.past(),
        updatedAt: faker.date.recent(),
      },
    });
  });

  const users = await Promise.all(userCreatePromises);
  users.forEach((user) => logger.info(`👤 Created user: ${user.name}`));

  // Create 3 organizations
  const memberPromises: Promise<unknown>[] = [];
  const invitationPromises: Promise<unknown>[] = [];

  // Prepare organization creation data
  const orgData = Array.from({ length: 3 }, () => {
    const orgName = faker.company.name();
    const orgSlug = orgName.toLowerCase().replace(/[^a-z0-9]/g, "-");
    return { orgName, orgSlug };
  });

  // Create all organizations first
  const organizations = await Promise.all(
    orgData.map(async ({ orgName, orgSlug }) =>
      prisma.organization
        .upsert({
          where: { slug: orgSlug },
          update: {},
          create: {
            id: nanoid(11),
            name: orgName,
            slug: orgSlug,
            logo: faker.image.url(),
            email: faker.internet.email(),
            createdAt: faker.date.past(),
          },
        })
        .then((org) => {
          logger.info(`🏢 Created organization: ${org.name}`);
          return org;
        }),
    ),
  );

  // Process members and invitations for each organization
  organizations.forEach((organization) => {
    const roleOptions = ["owner", "admin", "member"];

    // Make sure each org has at least one owner
    memberPromises.push(
      prisma.member
        .create({
          data: {
            id: nanoid(11),
            organizationId: organization.id,
            userId: users[0].id, // First user is always an owner
            role: "owner",
            createdAt: faker.date.past(),
          },
        })
        .then(() =>
          logger.info(
            `👑 Added ${users[0].name} as OWNER to ${organization.name}`,
          ),
        ),
    );

    // Add 2-4 more random members to each org
    const memberCount = faker.number.int({ min: 2, max: 4 });
    const memberIndices = faker.helpers.uniqueArray(
      () => faker.number.int({ min: 1, max: users.length - 1 }),
      memberCount,
    );

    for (const index of memberIndices) {
      const user = users[index];
      const role = faker.helpers.arrayElement(roleOptions);

      memberPromises.push(
        prisma.member
          .create({
            data: {
              id: nanoid(11),
              organizationId: organization.id,
              userId: user.id,
              role,
              createdAt: faker.date.past(),
            },
          })
          .then(() =>
            logger.info(
              `👥 Added ${user.name} as ${role} to ${organization.name}`,
            ),
          ),
      );
    }
  });

  await Promise.all([...memberPromises, ...invitationPromises]);

  // Update account types: users who are members of organizations should be professionals
  logger.info("🔄 Updating account types based on organization memberships...");

  const usersWithMemberships = await prisma.user.findMany({
    where: {
      members: {
        some: {},
      },
    },
    include: {
      members: {
        include: {
          organization: {
            select: { name: true },
          },
        },
      },
    },
  });

  const accountTypeUpdatePromises = usersWithMemberships.map(async (user) => {
    if (user.accountType !== "professional") {
      await prisma.user.update({
        where: { id: user.id },
        data: { accountType: "professional" },
      });

      const orgNames = user.members.map((m) => m.organization.name).join(", ");
      logger.info(
        `👔 Updated ${user.name} → professional (member of: ${orgNames})`,
      );
    }
  });

  await Promise.all(accountTypeUpdatePromises);

  // Create sample properties
  const propertiesData = Array.from({ length: 20 }, () => ({
    id: nanoid(11),
    externalId: faker.string.alphanumeric(10),
    title: faker.lorem.words(5),
    description: faker.lorem.paragraphs(2),
    type: faker.helpers.arrayElement(["sale", "rental"]),
    category: faker.helpers.arrayElement(["apartment", "house", "commercial"]),
    price: faker.number.int({ min: 100000, max: 2000000 }),
    surface: faker.number.int({ min: 20, max: 200 }),
    rooms: faker.number.int({ min: 1, max: 8 }),
    bedrooms: faker.number.int({ min: 1, max: 5 }),
    address: faker.location.streetAddress(),
    city: faker.location.city(),
    postalCode: faker.location.zipCode(),
    department: faker.location.county(),
    region: faker.location.state(),
    floor: faker.helpers.maybe(() => faker.number.int({ min: 0, max: 10 }), {
      probability: 0.7,
    }),
    totalFloors: faker.helpers.maybe(
      () => faker.number.int({ min: 1, max: 15 }),
      { probability: 0.7 },
    ),
    energyClass: faker.helpers.arrayElement([
      "A",
      "B",
      "C",
      "D",
      "E",
      "F",
      "G",
    ]),
    hasGarden: faker.datatype.boolean(0.3),
    hasParking: faker.datatype.boolean(0.6),
    hasLift: faker.datatype.boolean(0.4),
    hasTerrace: faker.datatype.boolean(0.4),
    hasBalcony: faker.datatype.boolean(0.7),
    sourceUrl: faker.internet.url(),
    sourceId: faker.string.alphanumeric(8),
    publishedAt: faker.date.recent({ days: 30 }),
  }));

  const properties = await Promise.all(
    propertiesData.map(async (propertyData) =>
      prisma.property.create({
        data: propertyData,
      }),
    ),
  );

  logger.info(`🏠 Created ${properties.length} properties`);

  // Create favorites for some users
  const favoritePromises = users.slice(0, 5).flatMap((user) =>
    faker.helpers
      .arrayElements(properties, { min: 2, max: 5 })
      .map(async (property) =>
        prisma.favorite.create({
          data: {
            id: nanoid(11),
            userId: user.id,
            propertyId: property.id,
            status: faker.helpers.arrayElement([
              "saved",
              "visited",
              "contacted",
              "rejected",
            ]),
            priority: faker.helpers.arrayElement(["high", "medium", "low"]),
            notes: faker.helpers.maybe(() => faker.lorem.sentences(2), {
              probability: 0.6,
            }),
            pricePerSqm: Math.round(property.price / (property.surface ?? 50)),
            confidenceScore: faker.number.int({ min: 50, max: 100 }),
            createdAt: faker.date.recent({ days: 15 }),
          },
        }),
      ),
  );

  const favorites = await Promise.all(favoritePromises);
  logger.info(`⭐ Created ${favorites.length} favorites`);

  // Create saved searches
  const savedSearchPromises = users.slice(0, 3).map(async (user) =>
    prisma.savedSearch.create({
      data: {
        id: nanoid(11),
        userId: user.id,
        name: faker.lorem.words(3),
        criteria: {
          types: ["sale"],
          categories: ["apartment", "house"],
          priceRange: {
            min: faker.number.int({ min: 100000, max: 300000 }),
            max: faker.number.int({ min: 500000, max: 1000000 }),
          },
          locations: [
            {
              city: faker.location.city(),
              radius: faker.number.int({ min: 5, max: 20 }),
            },
          ],
        },
        frequency: faker.helpers.arrayElement(["realtime", "daily", "weekly"]),
        createdAt: faker.date.recent({ days: 10 }),
      },
    }),
  );

  const savedSearches = await Promise.all(savedSearchPromises);
  logger.info(`🔍 Created ${savedSearches.length} saved searches`);

  // Create comparisons
  const comparisonPromises = users.slice(0, 2).map(async (user) =>
    prisma.comparison.create({
      data: {
        id: nanoid(11),
        userId: user.id,
        name: `Comparison ${faker.location.city()}`,
        createdAt: faker.date.recent({ days: 5 }),
      },
    }),
  );

  const comparisons = await Promise.all(comparisonPromises);

  // Add properties to comparisons
  const comparisonPropertyPromises = comparisons.flatMap((comparison) =>
    faker.helpers
      .arrayElements(properties, { min: 2, max: 4 })
      .map(async (property) =>
        prisma.comparisonProperty.create({
          data: {
            id: nanoid(11),
            comparisonId: comparison.id,
            propertyId: property.id,
            decision: faker.helpers.arrayElement(["go", "nogo", "negotiate"]),
            notes: faker.helpers.maybe(() => faker.lorem.sentences(1), {
              probability: 0.5,
            }),
          },
        }),
      ),
  );

  await Promise.all(comparisonPropertyPromises);
  logger.info(`📊 Created ${comparisons.length} comparisons`);

  // Final statistics
  logger.info("\n📈 Final Statistics:");

  const accountTypeStats = await prisma.user.groupBy({
    by: ["accountType"],
    _count: true,
  });

  logger.info("👥 Account Types:");
  for (const stat of accountTypeStats) {
    logger.info(`   ${stat.accountType}: ${stat._count} users`);
  }

  const orgMemberStats = await prisma.member.groupBy({
    by: ["role"],
    _count: true,
  });

  logger.info("🏢 Organization Roles:");
  for (const stat of orgMemberStats) {
    logger.info(`   ${stat.role}: ${stat._count} members`);
  }

  logger.info("✅ Seeding completed!");
}

main()
  .catch((e) => {
    logger.error("❌ Error seeding database:", e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

