"use server";

import { ActionError, authAction } from "@/lib/actions/safe-actions";
import { AUTH_PLANS } from "@/lib/auth/stripe/auth-plans";
import { getServerUrl } from "@/lib/server-url";
import { stripe } from "@/lib/stripe";
import { prisma } from "@/lib/prisma";
import { z } from "zod";

export const upgradeUserAction = authAction
  .inputSchema(
    z.object({
      plan: z.string(),
      annual: z.boolean().default(false),
      successUrl: z.string(),
      cancelUrl: z.string(),
    }),
  )
  .action(
    async ({
      parsedInput: { plan, annual, successUrl, cancelUrl },
      ctx: { user },
    }) => {
      const authPlan = AUTH_PLANS.find((p) => p.name === plan);
      if (!authPlan) {
        throw new ActionError(`Plan "${plan}" not found`);
      }

      const priceId = annual
        ? authPlan.annualDiscountPriceId
        : authPlan.priceId;
      if (!priceId) {
        throw new ActionError(`Price ID not found for plan "${plan}"`);
      }

      // Get or create Stripe customer for user
      const subscription = await prisma.subscription.findFirst({
        where: { userId: user.id },
      });

      let customerId = subscription?.stripeCustomerId;

      if (!customerId) {
        const customer = await stripe.customers.create({
          email: user.email,
          name: user.name,
          metadata: {
            userId: user.id,
          },
        });
        customerId = customer.id;
      }

      const session = await stripe.checkout.sessions.create({
        customer: customerId,
        payment_method_types: ["card"],
        line_items: [
          {
            price: priceId,
            quantity: 1,
          },
        ],
        mode: "subscription",
        success_url: `${getServerUrl()}${successUrl}?session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: `${getServerUrl()}${cancelUrl}`,
        metadata: {
          userId: user.id,
          plan: plan,
        },
        subscription_data: {
          metadata: {
            userId: user.id,
            plan: plan,
          },
          trial_period_days: authPlan.freeTrial?.days,
        },
      });

      if (!session.url) {
        throw new ActionError("Failed to create checkout session");
      }

      return {
        url: session.url,
      };
    },
  );

"use server";

import { ActionError, authAction } from "@/lib/actions/safe-actions";
import { fileAdapter } from "@/lib/files/placeholder-adapter";
import { z } from "zod";

export const uploadImageAction = authAction
  .inputSchema(
    z.object({
      formData: z.instanceof(FormData),
    }),
  )
  .action(async ({ parsedInput: { formData } }) => {
    const files = formData.get("files") as File | File[];

    let file: File;

    if (Array.isArray(files)) {
      file = files[0];
    } else {
      file = files;
    }

    if (!(file instanceof File)) {
      throw new ActionError("Invalid file (not a file)");
    }

    // If file is not an image throw an error
    if (!file.type.startsWith("image/")) {
      throw new ActionError("Invalid file (only images are allowed)");
    }

    // If file is too large throw an error (max 2mb)
    if (file.size > 2 * 1024 * 1024) {
      throw new ActionError("File too large (max 2mb)");
    }

    const response = await fileAdapter.uploadFile({
      file,
      path: "images",
    });

    if (response.error) {
      throw new ActionError(response.error.message);
    }

    return response.data.url;
  });

